from fastapi import FastAPI, Depends, Security
from fastapi.security import SecurityScopes
from fastapi.testclient import TestClient
from fastapi.dependencies.utils import get_dependant, solve_dependencies
from fastapi import Request

app = FastAPI()

def dep_a_sub(security_scopes: SecurityScopes):
    return security_scopes.scopes

def dep_a(security_scopes: SecurityScopes, sub = Security(dep_a_sub, scopes=["a_scope"])):
    return {"scopes": security_scopes.scopes, "sub": sub}

def dep_b(security_scopes: SecurityScopes):
    return security_scopes.scopes

def root(
    a = Security(dep_a, scopes=["root_scope"]),
    b = Security(dep_b, scopes=["root_scope"]),
):
    return {"a": a, "b": b}

# We need to simulate the dependency resolution
# In a real app, FastAPI does this.

# Let's use a real app and a test client.
@app.get("/")
def read_root(res = Depends(root)):
    return res

client = TestClient(app)

def test_scopes():
    response = client.get("/")
    print(response.json())
    # Expected: a['scopes'] = ['root_scope'], a['sub'] = ['root_scope', 'a_scope'], b = ['root_scope']
    # Actual if bug exists: b = ['root_scope', 'a_scope']

if __name__ == "__main__":
    test_scopes()

